/**
 * Access to the per-participant record, and only transparent derivations.
 *
 * SOURCE OF TRUTH
 * `data/participants.json` is generated by
 * scripts/export_participant_explorer.py, which disaggregates the frozen
 * experiment's own held-out evaluation. Every value here comes from that file.
 * Nothing in this module invents a metric, a threshold or an interval.
 *
 * WHAT COUNTS AS AN ALLOWED DERIVATION
 * Selecting, sorting, formatting, and arithmetic whose inputs are all visible
 * on screen (a difference between two published numbers, a count of records
 * matching a published band). Anything that would require a new statistical
 * definition belongs in the exporter, next to the methodology, not here.
 */
import P from "../data/participants.json";

export const META = {
  provenance: P._provenance,
  anonymisation: P._anonymisation,
  definitions: P._definitions,
  uncertainty: P._uncertainty,
  split: P.split,
  kPrimary: P.K_primary,
  kGrid: P.K_grid,
  nTest: P.n_test_participants,
  nScored: P.n_scored_primary,
  nTwinBetter: P.n_twin_better_primary,
  redistribution: P._redistribution,
  seriesMode: P.series_mode,
  illustrativeRule: P.illustrative_rule,
  illustrativeIds: P.illustrative_ids || [],
  nSeriesPublished: P.n_series_published,
};

/**
 * Does this participant's observation series ship with the site?
 *
 * The source archive is not redistributed, so only an illustrative subset
 * carries its series; everyone else carries statistics alone. A page must ask
 * this before trying to draw a chart, and say so when the answer is no --
 * never render an empty chart that reads as a failure.
 */
export function hasSeries(p) {
  return Boolean(p && Array.isArray(p.series) && p.series.length);
}

export const PARTICIPANTS = P.participants;

/** Every participant, newest-first by nothing -- stable label order. */
export function all() {
  return PARTICIPANTS;
}

export function byId(id) {
  return PARTICIPANTS.find((p) => p.id === id) || null;
}

/** The per-K block, or null when the frozen protocol did not score them. */
export function scoreAt(p, K = META.kPrimary) {
  const k = p?.by_K?.[String(K)];
  return k && k.scored ? k : null;
}

export function isScored(p, K = META.kPrimary) {
  return scoreAt(p, K) !== null;
}

/** Why a participant has no score, in the protocol's own words. */
export function unscoredReason(p, K = META.kPrimary) {
  return p?.by_K?.[String(K)]?.reason || "not scored";
}

/**
 * Sort options. Each one orders by a published field; none computes a rank
 * from anything the interface does not also show.
 */
export const SORTS = {
  label: { label: "Participant", get: (p) => p.id, text: true },
  autocorrelation: { label: "Autocorrelation", get: (p) => p.autocorrelation },
  observations: { label: "Observations", get: (p) => p.n_observations },
  advantage: {
    label: "Twin − persistence",
    get: (p) => scoreAt(p)?.twin_minus_persistence_macro_f1 ?? null,
  },
};

export function sorted(key = "label", descending = false) {
  const s = SORTS[key] || SORTS.label;
  const rows = [...PARTICIPANTS];
  rows.sort((a, b) => {
    const x = s.get(a), y = s.get(b);
    if (x == null && y == null) return 0;
    if (x == null) return 1;                     // missing values sink
    if (y == null) return -1;
    if (s.text) return descending ? String(y).localeCompare(String(x))
                                  : String(x).localeCompare(String(y));
    return descending ? y - x : x - y;
  });
  return rows;
}

/** Counts per published band. A tally of a field, not a new classification. */
export function bandCounts() {
  const out = { "well-predictable": 0, typical: 0, "near-unpredictable": 0 };
  for (const p of PARTICIPANTS) {
    if (p.predictability_band in out) out[p.predictability_band] += 1;
  }
  return out;
}

/** Where this participant's r sits among the others, as a plain count. */
export function rankByAutocorrelation(p) {
  const rs = PARTICIPANTS.map((x) => x.autocorrelation)
    .filter((r) => r != null).sort((a, b) => a - b);
  if (p.autocorrelation == null) return null;
  return { position: rs.filter((r) => r < p.autocorrelation).length + 1,
           of: rs.length };
}

/** The illustrative participants, in the order they are published. */
export function illustrative() {
  return META.illustrativeIds.map(byId).filter(Boolean);
}

/** The observed series split into the two phases the protocol defines. */
export function phases(p) {
  const series = Array.isArray(p?.series) ? p.series : [];
  const warm = series.filter((s) => s.warmup);
  const evaluated = series.filter((s) => !s.warmup);
  return { warm, evaluated, hasPredictions: evaluated.some((s) => s.predicted != null) };
}

/** Formatting helpers, kept here so every surface renders a number the same. */
export const fmt = {
  f2: (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(2)),
  f3: (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(3)),
  f4: (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(4)),
  signed: (x) => (x == null || !isFinite(x) ? "—"
                  : (x >= 0 ? "+" : "") + x.toFixed(4)),
  int: (x) => (x == null ? "—" : String(x)),
};
